import java.io.*;
import java.util.*;

public class E {
    private static final int oo = 1000000000;
    public static void main(String[] args) throws Exception {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int m = in.nextInt();
        if (n > m) {
            int t = n; n = m; m = t;
        }
        int size = 1 << n;
        int[][] curr = new int[size][size];
        for (int i = 0; i < size; i++) {
            int j = 0;
            while (j < size) {
                curr[i][j] = oo;
                j++;
            }
        }
        int j = 0;
        while (j < size) {
            curr[0][j] = 0;
            j++;
        }
        int col = 0;
        while (col < m) {
            int[][] next = new int[size][size];
            for (int i = 0; i < size; i++) {
                int j2 = 0;
                while (j2 < size) {
                    next[i][j2] = oo;
                    j2++;
                }
            }
            int limit = (col == m - 1) ? 1 : size;
            int c0 = 0;
            while (c0 < size) {
                int[] currRow = curr[c0];
                int c1 = 0;
                while (c1 < size) {
                    int curVal = currRow[c1];
                    if (curVal != oo) {
                        int c2 = 0;
                        while (c2 < limit) {
                            int done = 0;
                            int i = 0;
                            while (i < n) {
                                if (((1 << i) & c1) == 0) {
                                    int up = i - 1, down = i + 1;
                                    if (up >= 0 && ((1 << up) & c1) != 0) done |= 1 << i;
                                    if (down < n && ((1 << down) & c1) != 0) done |= 1 << i;
                                    if (((1 << i) & c0) != 0) done |= 1 << i;
                                    if (((1 << i) & c2) != 0) done |= 1 << i;
                                }
                                i++;
                            }
                            int newVal = curVal + n - Integer.bitCount(done);
                            if (newVal < next[c1][c2]) next[c1][c2] = newVal;
                            c2++;
                        }
                    }
                    c1++;
                }
                c0++;
            }
            curr = next;
            col++;
        }
        int res = oo;
        for (int i = 0; i < size; i++) {
            for (int j2 = 0; j2 < size; j2++) {
                if (curr[i][j2] < res) res = curr[i][j2];
            }
        }
        System.out.println(n * m - res);
    }
}
